with kept_keys as (select city from stores intersect select city from stores where region = 'East'), kept_rows as (select s.* from stores s join kept_keys k on s.city = k.city) select region, count(distinct region) as distinct_regions, round(sum(sqft) / nullif(count(case when region = 'Central' then 1 end), 0), 2) as sqft_per_central, max(sqft) filter (where region = 'West') as west_max_sqft, count(distinct id) as distinct_ids from kept_rows group by region;
